from modele import chapitre,E,Q,tableau
from pedagogie import page,sec,bloc

chapitre(10,'longueurs','Longueurs et périmètres','2 · Modéliser et mesurer',
'Unités · Contours · Disque et nombre pi · Figures composées',
['Choisir une unité et convertir une longueur.','Calculer le périmètre d’un carré, d’un rectangle et d’un disque.','Décomposer un contour et contrôler un calcul de longueur.'],
['Numération décimale ; périmètre comme longueur d’un contour.'],[
page(1,'Mesurer, estimer et convertir',
bloc('definition',r'Les unités de longueur sont construites à partir du mètre avec des préfixes : kilo- signifie mille, hecto- cent, déca- dix ; déci- un dixième, centi- un centième, milli- un millième. Ainsi 1 km $=1\,000$ m ; 1 hm $=100$ m ; 1 dam $=10$ m ; 1 dm $=0{,}1$ m ; 1 cm $=0{,}01$ m ; 1 mm $=0{,}001$ m.'),
bloc('savoirfaire',r'Deux unités voisines sont dans un rapport de 10 : 1 dm $=10$ cm et 1 cm $=\frac1{10}$ dm $=0{,}1$ dm. Pour convertir en mètres, on se demande combien de mètres vaut l’unité : $3{,}7$ km $=3{,}7\times1\,000$ m $=3\,700$ m ; 45 cm $=45\times0{,}01$ m $=0{,}45$ m.','Convertir en mètres'),
sec(2,'Périmètres du carré et du rectangle'),
bloc('definition',r'Le périmètre d’une figure plane est la longueur de son contour.'),
bloc('propriete',r'Carré de côté $c$ : $P=4\times c$. Rectangle de longueur $L$ et de largeur $\ell$ : $P=2\times(L+\ell)$. Pour un carré de côté $3{,}5$ cm, on remplace $c$ par $3{,}5$ : $P=4\times3{,}5=14$ cm.'),
bloc('attention',r'Les longueurs doivent être exprimées dans la même unité : un rectangle de 2 m sur 80 cm a pour périmètre $2\times(2+0{,}8)=5{,}6$ m.')),
page(3,'Périmètre du disque et nombre pi',
bloc('propriete',r'Le périmètre d’un disque est proportionnel à son diamètre : on multiplie toujours le diamètre par le même nombre, noté $\pi$ (« pi »), qui vaut environ $3{,}14$. Si $d$ est le diamètre et $r$ le rayon : $P=\pi\times d=2\times\pi\times r$.'),
r'@FIG:cours-cercle-diametre@',
bloc('exemple',r'Disque de diamètre 10 cm : $P=\pi\times10$ cm, valeur exacte ; $P\approx3{,}14\times10=31{,}4$ cm, valeur approchée. Le nombre $\pi$ n’est pas décimal : $3{,}14$ en est seulement un arrondi.'),
sec(4,'Contours de figures composées'),
bloc('savoirfaire',r'On parcourt le contour sans compter les segments intérieurs. Un rectangle de 6 cm sur 4 cm prolongé par un demi-disque de diamètre 4 cm a pour contour $6+4+6$ cm, plus un demi-périmètre de disque, $\pi\times4:2\approx6{,}28$ cm : environ $22{,}28$ cm.','Suivre le contour')),
],[
E('Convertir en mètres',r'Convertir en mètres : $3{,}7$ km ; 45 cm ; 2 hm ; 8 mm ; 6 dam.',r'$\res{3\,700}$ m ; $\res{0{,}45}$ m ; $\res{200}$ m ; $\res{0{,}008}$ m ; $\res{60}$ m.','Multiplier par la valeur de l’unité en mètres.','assert Rational("3.7")*1000==3700 and 45*Rational(1,100)==Rational(".45") and 2*100==200 and 8*Rational(1,1000)==Rational(".008") and 6*10==60'),
E('Convertir depuis le mètre',r'Convertir : $0{,}8$ m en cm ; $1\,250$ m en km ; $2{,}5$ m en mm ; 30 m en dam.',r'$\res{80}$ cm ; $\res{1{,}25}$ km ; $\res{2\,500}$ mm ; $\res3$ dam.','1 m vaut 100 cm, 1 000 mm ; 1 km vaut 1 000 m.','assert Rational(".8")*100==80 and Rational(1250,1000)==Rational("1.25") and Rational("2.5")*1000==2500 and 30//10==3'),
E('Carré et rectangle',r'Calculer le périmètre d’un carré de côté $3{,}5$ cm, puis celui d’un rectangle de $7{,}2$ m sur $4{,}5$ m.',r'Carré : $4\times3{,}5=\res{14\ \mathrm{cm}}$. Rectangle : $2\times(7{,}2+4{,}5)=2\times11{,}7=\res{23{,}4\ \mathrm{m}}$.','Remplacer les lettres des formules par les mesures.','assert 4*Rational("3.5")==14 and 2*(Rational("7.2")+Rational("4.5"))==Rational("23.4")'),
E('Périmètre d’un disque',r'Calculer la valeur exacte, puis une valeur approchée avec $\pi\approx3{,}14$, du périmètre d’un disque de diamètre 10 cm, puis d’un disque de rayon 5 m.',r'$\pi\times10$ cm, soit environ $\res{31{,}4\ \mathrm{cm}}$. Rayon 5 m : diamètre 10 m, périmètre $10\pi$ m, environ $\res{31{,}4\ \mathrm{m}}$.','Le diamètre vaut deux rayons.','assert Rational("3.14")*10==Rational("31.4") and 2*5==10'),
E('Reporter au compas',r'Sans règle graduée, reporter au compas les trois côtés de la ligne brisée ABCD bout à bout sur la demi-droite, à partir de son origine O. Mesurer ensuite la longueur obtenue.',r'Les reports figurent en vert. On obtient $2{,}3+1{,}8+2{,}6=\res{6{,}7\ \mathrm{cm}}$ : c’est la longueur de la ligne brisée.','Le compas transporte une longueur sans la mesurer.','assert Rational("2.3")+Rational("1.8")+Rational("2.6")==Rational("6.7")',figure='lon-5'),
E('Une figure composée',r'La figure est formée d’un rectangle de 6 cm sur 4 cm et d’un demi-disque de diamètre 4 cm. Calculer une valeur approchée de son périmètre.',r'Côtés droits : $6+4+6=16$ cm. Demi-cercle : $3{,}14\times4:2=6{,}28$ cm. Périmètre : environ $\res{22{,}28\ \mathrm{cm}}$.','Ne pas compter le segment intérieur.','assert 6+4+6+Rational("3.14")*4/2==Rational("22.28")',figure='lon-6'),
E('Le tour du stade',r'Une piste est formée de deux lignes droites de 100 m et de deux demi-cercles de 60 m de diamètre. Calculer la longueur d’un tour, au dixième de mètre.',r'Les deux demi-cercles forment un cercle entier : $3{,}14\times60=188{,}4$ m. Un tour : $2\times100+188{,}4=\res{388{,}4\ \mathrm{m}}$ environ.','Assembler les deux demi-cercles.','assert 2*100+Rational("3.14")*60==Rational("388.4")',figure='lon-7'),
E('Retrouver une dimension',r'Un rectangle a pour périmètre 30 cm et pour longueur 9 cm. Quelle est sa largeur ? Un carré a pour périmètre 26 cm : quel est son côté ?',r'Une longueur plus une largeur font $30:2=15$ cm : largeur $15-9=\res6$ cm. Côté du carré : $26:4=\res{6{,}5}$ cm.','Le demi-périmètre vaut L plus l.','assert 2*(9+6)==30 and 4*Rational("6.5")==26'),
E('Proportionnel au diamètre',r'Recopier et compléter avec $\pi\approx3{,}14$. Que devient le périmètre quand le diamètre est multiplié par 3 ?'+tableau(['Diamètre (cm)','1','2','5','10','20'],[['Périmètre (cm)','…','…','…','…','…']]),r'$\res{3{,}14}$ ; $\res{6{,}28}$ ; $\res{15{,}7}$ ; $\res{31{,}4}$ ; $\res{62{,}8}$. Quand le diamètre est multiplié par 3, le périmètre est aussi multiplié par 3 : c’est une situation de proportionnalité.','Multiplier chaque diamètre par 3,14.','p=Rational("3.14")\nassert [p*d for d in (1,2,5,10,20)]==[p,Rational("6.28"),Rational("15.7"),Rational("31.4"),Rational("62.8")]'),
E('Le contour d’un L',r'Les angles de la figure sont droits. Calculer les deux longueurs manquantes, puis le périmètre de la figure.',r'Côté horizontal manquant : $8-3=\res5$ cm. Côté vertical manquant : $7-3=\res4$ cm. Périmètre : $8+3+5+4+3+7=\res{30\ \mathrm{cm}}$.','Utiliser les côtés opposés de même direction.','assert 8-3==5 and 7-3==4 and 8+3+5+4+3+7==30',figure='lon-10'),
E('La roue du vélo',r'La roue d’un vélo a un diamètre de 70 cm. Quelle distance parcourt le vélo quand la roue fait un tour ? Et 1 000 tours ? Répondre en mètres, puis en kilomètres pour 1 000 tours.',r'Un tour : $3{,}14\times70=219{,}8$ cm, soit $\res{2{,}198\ \mathrm{m}}$ environ. 1 000 tours : $2\,198$ m, soit environ $\res{2{,}2\ \mathrm{km}}$.','Un tour de roue fait avancer d’un périmètre.','assert Rational("3.14")*70==Rational("219.8") and Rational("2.198")*1000==2198'),
E('La clôture',r'Un jardin rectangulaire mesure $18{,}5$ m sur 12 m. On le clôture entièrement, sauf un portail de $1{,}5$ m. Le grillage coûte $2{,}40$ € le mètre. Quelle longueur de grillage faut-il ? Quel est son prix ?',r'Périmètre : $2\times(18{,}5+12)=61$ m. Grillage : $61-1{,}5=\res{59{,}5\ \mathrm{m}}$. Prix : $59{,}5\times2{,}40=\res{142{,}80}$ €.','Retirer la longueur du portail.','assert 2*(Rational("18.5")+12)==61 and 61-Rational("1.5")==Rational("59.5") and Rational("59.5")*Rational("2.4")==Rational("142.8")'),
E('Le marathon',r'Un marathon mesure $42{,}195$ km. Un tour de piste d’athlétisme mesure 400 m. Combien de tours complets faudrait-il faire, et quelle distance resterait-il ?',r'$42{,}195$ km $=42\,195$ m et $42\,195=400\times105+195$ : $\res{105}$ tours complets et $\res{195\ \mathrm{m}}$ de plus.','Convertir, puis effectuer une division euclidienne.','assert Rational("42.195")*1000==42195 and divmod(42195,400)==(105,195)'),
E('Le rond-point',r'Un rond-point est un cercle de 15 m de rayon. Une voiture en fait les trois quarts. Quelle distance parcourt-elle environ ?',r'Tour complet : $2\times3{,}14\times15=94{,}2$ m. Trois quarts : $94{,}2:4\times3=\res{70{,}65\ \mathrm{m}}$ environ.','Calculer le tour entier, puis la fraction.','assert 2*Rational("3.14")*15==Rational("94.2") and Rational("94.2")/4*3==Rational("70.65")',figure='lon-14'),
E('Vrai ou faux',r'Dire si chaque phrase est vraie ou fausse, en justifiant.'+Q(r'Si le côté d’un carré double, son périmètre double.',r'Deux rectangles de même périmètre sont superposables.'),r'1. $\res{\text{Vrai}}$ : $4\times(2\times c)=2\times(4\times c)$. 2. $\res{\text{Faux}}$ : un rectangle de 5 cm sur 1 cm et un carré de 3 cm de côté ont tous deux un périmètre de 12 cm.','Chercher un contre-exemple.','assert 2*(5+1)==4*3==12')
],reperes=['Unités de longueur et conversions','Périmètres du carré et du rectangle','Périmètre du disque','Figures composées et problèmes'],deco='grandeurs')

chapitre(11,'aires','Comparer et mesurer des aires','2 · Modéliser et mesurer',
'Surfaces · Unités carrées · Conversions · Formules',
['Comparer des aires par superposition ou par découpage.','Utiliser les unités cm², dm² et m² et convertir entre elles.','Calculer l’aire d’un carré et d’un rectangle avec une formule.'],
['Quadrillages ; multiplication des décimaux ; périmètre.'],[
page(1,'Comparer sans mesurer',
bloc('definition',r'L’aire d’une surface mesure la place qu’elle occupe. Deux surfaces ont la même aire si l’on peut découper l’une et recoller ses morceaux pour recouvrir exactement l’autre.'),
r'@FIG:cours-decoupage@',
bloc('attention',r'Aire et périmètre sont deux grandeurs différentes : en découpant et recollant, l’aire ne change pas, alors que le périmètre peut changer.'),
sec(2,'Comprendre les unités carrées'),
bloc('definition',r'1 cm$^2$ est l’aire d’un carré de 1 cm de côté ; 1 dm$^2$, celle d’un carré de 1 dm de côté ; 1 m$^2$, celle d’un carré de 1 m de côté.'),
bloc('savoirfaire',r'Sur un quadrillage de carreaux de 1 cm de côté, chaque carreau a une aire de 1 cm$^2$ ; deux demi-carreaux font 1 cm$^2$.','Compter les carreaux')),
page(3,'Convertir entre unités d’aire voisines',
bloc('propriete',r'$1\ \mathrm{m}^2=1\ \mathrm m\times1\ \mathrm m=10\ \mathrm{dm}\times10\ \mathrm{dm}=100\ \mathrm{dm}^2$ et $1\ \mathrm{dm}^2=100\ \mathrm{cm}^2$. Dans l’autre sens : $1\ \mathrm{cm}^2=\frac1{100}\ \mathrm{dm}^2=0{,}01\ \mathrm{dm}^2$ et $1\ \mathrm{dm}^2=0{,}01\ \mathrm{m}^2$.'),
r'@FIG:cours-dm2@',
bloc('attention',r'Entre deux unités d’aire voisines, le rapport est 100, et non 10 : un carré de 10 cm de côté contient 10 rangées de 10 carreaux de 1 cm$^2$.'),
sec(4,'Aires du carré et du rectangle'),
bloc('propriete',r'Aire d’un carré de côté $c$ : $A=c\times c$. Aire d’un rectangle de longueur $L$ et de largeur $\ell$ : $A=L\times\ell$, les deux longueurs étant dans la même unité.'),
bloc('exemple',r'Rectangle de $3{,}5$ m sur 2 m : $A=3{,}5\times2=7\ \mathrm{m}^2$. Carré de 7 cm de côté : $A=7\times7=49\ \mathrm{cm}^2$.')),
],[
E('Comparer sans mesurer',r'Ranger les surfaces A, B et C selon leur aire, sans règle. Deux demi-carreaux forment un carreau.',r'A : 8 carreaux. B : 7 carreaux. C : 6 carreaux et deux demi-carreaux, soit 7 carreaux. Donc $\res{B\text{ et }C}$ ont la même aire, plus petite que celle de A.','Compter les carreaux et assembler les moitiés.','assert 8>7==6+2*Rational(1,2)',figure='air-1'),
E('Compter les carreaux',r'Chaque carreau mesure 1 cm de côté. Quelle est l’aire de la figure ?',r'Le rectangle de 5 sur 3 compte 15 carreaux ; il en manque 2. Aire : $15-2=\res{13\ \mathrm{cm}^2}$.','Compléter en rectangle, puis retirer.','assert 5*3-2==13',figure='air-2'),
E('Choisir l’unité',r'Quelle unité, parmi cm$^2$, dm$^2$ et m$^2$, convient le mieux pour l’aire : d’un timbre ; d’une page de cahier ; du sol d’une chambre ?',r'Timbre : $\res{\mathrm{cm}^2}$. Page de cahier : $\res{\mathrm{dm}^2}$, environ 6 dm$^2$. Chambre : $\res{\mathrm m^2}$, environ 10 m$^2$.','Imaginer le carré unité à côté de l’objet.','assert 100*6==600'),
E('Avec les formules',r'Calculer l’aire d’un carré de 7 cm de côté, puis celle d’un rectangle de 12 m sur $4{,}5$ m.',r'Carré : $7\times7=\res{49\ \mathrm{cm}^2}$. Rectangle : $12\times4{,}5=\res{54\ \mathrm{m}^2}$.','Remplacer les lettres par les mesures.','assert 7*7==49 and 12*Rational("4.5")==54'),
E('Convertir',r'Convertir : 3 m$^2$ en dm$^2$ ; 5 dm$^2$ en cm$^2$ ; 400 cm$^2$ en dm$^2$ ; 250 dm$^2$ en m$^2$.',r'$\res{300\ \mathrm{dm}^2}$ ; $\res{500\ \mathrm{cm}^2}$ ; $\res{4\ \mathrm{dm}^2}$ ; $\res{2{,}5\ \mathrm{m}^2}$.','Le rapport entre unités voisines est 100.','assert 3*100==300 and 5*100==500 and Rational(400,100)==4 and Rational(250,100)==Rational("2.5")'),
E('Conversions décimales',r'Convertir : $0{,}7$ m$^2$ en dm$^2$ ; 45 cm$^2$ en dm$^2$ ; $3{,}2$ dm$^2$ en cm$^2$ ; 8 dm$^2$ en m$^2$.',r'$\res{70\ \mathrm{dm}^2}$ ; $\res{0{,}45\ \mathrm{dm}^2}$ ; $\res{320\ \mathrm{cm}^2}$ ; $\res{0{,}08\ \mathrm{m}^2}$.','Multiplier ou diviser par 100.','assert Rational(".7")*100==70 and Rational(45,100)==Rational(".45") and Rational("3.2")*100==320 and Rational(8,100)==Rational(".08")'),
E('Même aire, autre périmètre',r'Calculer l’aire et le périmètre de chacun des deux rectangles. Que remarque-t-on ?',r'Rectangle de 6 cm sur 2 cm : aire $\res{12\ \mathrm{cm}^2}$, périmètre 16 cm. Rectangle de 4 cm sur 3 cm : aire $\res{12\ \mathrm{cm}^2}$, périmètre 14 cm. Même aire, périmètres différents.','Calculer séparément les deux grandeurs.','assert 6*2==4*3==12 and 2*(6+2)==16 and 2*(4+3)==14',figure='air-7'),
E('Découper et recoller',r'On découpe le triangle grisé et on le recolle de l’autre côté. Quelle figure obtient-on ? En déduire l’aire de la figure de départ.',r'Le triangle recollé à droite complète un rectangle de 4 carreaux sur 3, visible en vert. L’aire de la figure de départ est donc $4\times3=\res{12\ \mathrm{cm}^2}$.','Transformer la figure en rectangle sans changer l’aire.','assert 4*3==12',figure='air-8'),
E('Retrouver une longueur',r'Un rectangle a une aire de 36 cm$^2$ et une longueur de 9 cm. Quelle est sa largeur ? Un carré a une aire de 64 m$^2$ : quelle est la longueur de son côté ?',r'$9\times\square=36$ : largeur $\res4$ cm. $c\times c=64$ : $c=\res8$ m, car $8\times8=64$.','Chercher le facteur manquant.','assert 9*4==36 and 8*8==64'),
E('La pièce en L',r'Les angles du plan sont droits. Calculer l’aire de la pièce de deux façons.',r'Découpage : $9\times3+4\times4=27+16=\res{43\ \mathrm{m}^2}$. Complément : $9\times7-5\times4=63-20=43\ \mathrm{m}^2$. Les deux méthodes concordent.','Découper en rectangles, ou compléter puis retirer.','assert 9*3+4*4==43==9*7-5*4',figure='air-10'),
E('Le carrelage',r'On carrelle le sol d’une pièce rectangulaire de 4 m sur $3{,}5$ m avec des carreaux carrés de 1 dm de côté. Combien de carreaux faut-il ?',r'Aire : $4\times3{,}5=14\ \mathrm{m}^2$, soit $14\times100=1\,400\ \mathrm{dm}^2$. Chaque carreau couvre 1 dm$^2$ : $\res{1\,400}$ carreaux.','Convertir l’aire dans l’unité du carreau.','assert 4*Rational("3.5")==14 and 14*100==1400 and 40*35==1400'),
E('La peinture',r'Un mur mesure 5 m sur $2{,}5$ m ; il comporte une porte de $0{,}9$ m sur 2 m, qu’on ne peint pas. Un pot de peinture couvre 5 m$^2$. Combien de pots faut-il acheter ?',r'Mur : $12{,}5$ m$^2$. Porte : $1{,}8$ m$^2$. À peindre : $\res{10{,}7\ \mathrm{m}^2}$. Deux pots couvrent 10 m$^2$, c’est trop peu : il faut $\res3$ pots.','Retirer l’aire de la porte, puis interpréter la division.','assert 5*Rational("2.5")-Rational(".9")*2==Rational("10.7") and 2*5<Rational("10.7")<=3*5'),
E('Le jardin partagé',r'Un jardin carré de 20 m de côté est partagé entre un potager rectangulaire de 20 m sur 8 m et une pelouse. Calculer l’aire du potager, puis celle de la pelouse. Quel pourcentage du jardin le potager occupe-t-il ?',r'Jardin : 400 m$^2$. Potager : $20\times8=\res{160\ \mathrm{m}^2}$. Pelouse : $400-160=\res{240\ \mathrm{m}^2}$. Proportion : $\frac{160}{400}=\frac{40}{100}$, soit $\res{40\text{~\%}}$.','Calculer les aires, puis la proportion.','assert 20*20==400 and 20*8==160 and 400-160==240 and Rational(160,400)==Rational(40,100)',figure='air-13'),
E('Des timbres sur une affiche',r'Des timbres rectangulaires de 3 cm sur $2{,}5$ cm recouvrent sans chevauchement une affiche de 6 dm sur 4 dm. Combien de timbres faut-il ?',r'Timbre : $3\times2{,}5=7{,}5$ cm$^2$. Affiche : $6\times4=24$ dm$^2$, soit $2\,400$ cm$^2$. Nombre : $2\,400:7{,}5=\res{320}$. Contrôle : 20 timbres sur 60 cm et 16 timbres sur 40 cm, $20\times16=320$.','Exprimer les deux aires dans la même unité.','assert 3*Rational("2.5")==Rational("7.5") and 24*100==2400 and 2400/Rational("7.5")==320 and (60//3)*(40/Rational("2.5"))==320'),
E('Vrai ou faux',r'Lucie affirme : « Si on double le côté d’un carré, son aire double. » Vérifier avec un carré de 3 cm de côté.',r'Côté 3 cm : aire 9 cm$^2$. Côté 6 cm : aire 36 cm$^2$, quatre fois plus. C’est $\res{\text{faux}}$ : l’aire est multipliée par $\res4$.','Tester sur un exemple.','assert 6*6==4*(3*3)')
],reperes=['Comparer des aires sans mesurer','Unités d’aire et quadrillages','Conversions d’aires','Formules et problèmes'],deco='grandeurs')

chapitre(12,'durees','Horaires et durées','2 · Modéliser et mesurer',
'Instants · Intervalles · Base soixante · Heures décimales',
['Distinguer un horaire d’une durée et lire l’heure.','Calculer un début, une fin ou un temps écoulé.','Convertir des durées et relier heures décimales et heures-minutes.'],
['Lecture de l’heure ; jour, heure, minute, seconde.'],[
page(1,'Lire et représenter un horaire',
bloc('definition',r'Un horaire indique un instant : 14 h 32 min 5 s. Une durée mesure le temps écoulé entre deux instants : 1 h 28 min.'),
bloc('propriete',r'1 jour $=24$ h ; 1 h $=60$ min ; 1 min $=60$ s ; donc 1 h $=3\,600$ s. Une année compte 365 jours, ou 366 si elle est bissextile ; un siècle dure 100 ans, un millénaire $1\,000$ ans. Une demi-heure dure 30 min, un quart d’heure 15 min, trois quarts d’heure 45 min.'),
sec(2,'Calculer un temps écoulé'),
bloc('savoirfaire',r'De 9 h 47 à 11 h 15 : 13 min pour atteindre 10 h, puis 1 h pour atteindre 11 h, puis 15 min. Durée : $13+15=28$ min et 1 h, soit 1 h 28 min.','Avancer par étapes'),
r'@FIG:cours-frise@',
bloc('exemple',r'Un film commence à 20 h 50 et dure 1 h 45 min. 10 min mènent à 21 h ; il reste 1 h 35 min : le film finit à 22 h 35.')),
page(3,'Convertir des durées',
bloc('savoirfaire',r'200 min : $200=60\times3+20$, soit 3 h 20 min. De même, $1\,000$ s : $1\,000=60\times16+40$, soit 16 min 40 s. Les durées se comptent par soixante, comme chez les Babyloniens il y a quatre mille ans.','Diviser par 60'),
sec(4,'Relier les écritures d’une durée'),
bloc('propriete',r'Une durée peut s’écrire en heures décimales : $1{,}5$ h $=1$ h 30 min, car $0{,}5$ h est la moitié de 60 min ; $0{,}25$ h $=15$ min ; $0{,}1$ h $=6$ min. Inversement, 2 h 45 min $=2{,}75$ h.'),
r'@FIG:cours-cadran@',
bloc('attention',r'$1{,}30$ h ne vaut pas 1 h 30 min : $0{,}3$ h, c’est $0{,}3\times60=18$ min. Donc $1{,}3$ h $=1$ h 18 min.')),
],[
E('Lire l’heure',r'Les horloges indiquent des horaires de l’après-midi. Les écrire en heures et minutes, de 0 h à 24 h.',r'$\res{15\text{ h }20}$ ; $\res{19\text{ h }45}$ ; $\res{23\text{ h }05}$ : on ajoute 12 h aux heures lues sur le cadran.','Lire la petite aiguille, puis la grande.','assert 3+12==15 and 7+12==19 and 11+12==23',figure='dur-1'),
E('Unités de durée',r'Compléter : 1 h $=\square$ s ; 3 jours $=\square$ h ; 2 min 15 s $=\square$ s ; 1 millénaire $=\square$ siècles.',r'$\res{3\,600}$ s ; $\res{72}$ h ; $\res{135}$ s ; $\res{10}$ siècles.','Utiliser les relations entre unités.','assert 60*60==3600 and 3*24==72 and 2*60+15==135 and 1000//100==10'),
E('Fractions d’heure',r'Combien de minutes dans : un quart d’heure ; trois quarts d’heure ; une demi-heure ; un tiers d’heure ?',r'$\res{15}$ min ; $\res{45}$ min ; $\res{30}$ min ; $60:3=\res{20}$ min.','Prendre la fraction de 60 minutes.','assert Rational(1,4)*60==15 and Rational(3,4)*60==45 and Rational(1,2)*60==30 and Rational(1,3)*60==20'),
E('Calculer une durée',r'Un cours de musique commence à 9 h 47 et se termine à 11 h 15. Combien de temps dure-t-il ?',r'9 h 47 → 10 h : 13 min ; 10 h → 11 h : 1 h ; 11 h → 11 h 15 : 15 min. Durée : $\res{1\text{ h }28\text{ min}}$.','Avancer jusqu’aux heures rondes.','assert (11*60+15)-(9*60+47)==88 and divmod(88,60)==(1,28)'),
E('Heure d’arrivée',r'Un car part à 14 h 35. Le trajet dure 2 h 50 min. À quelle heure arrive-t-il ?',r'14 h 35 + 2 h = 16 h 35 ; + 25 min = 17 h ; + 25 min = 17 h 25. Arrivée : $\res{17\text{ h }25}$.','Ajouter les heures, puis les minutes en passant par l’heure ronde.','assert divmod(14*60+35+2*60+50,60)==(17,25)'),
E('Convertir',r'Convertir en heures et minutes : 200 min ; 135 min. Convertir $1\,000$ s en minutes et secondes.',r'$200=60\times3+20$ : $\res{3\text{ h }20\text{ min}}$. $135=60\times2+15$ : $\res{2\text{ h }15\text{ min}}$. $1\,000=60\times16+40$ : $\res{16\text{ min }40\text{ s}}$.','Division euclidienne par 60.','assert divmod(200,60)==(3,20) and divmod(135,60)==(2,15) and divmod(1000,60)==(16,40)'),
E('Heures décimales',r'Écrire en heures et minutes : $1{,}5$ h ; $2{,}25$ h ; $0{,}1$ h ; $3{,}75$ h.',r'$\res{1\text{ h }30\text{ min}}$ ; $\res{2\text{ h }15\text{ min}}$ ; $\res{6\text{ min}}$ ; $\res{3\text{ h }45\text{ min}}$.','Multiplier la partie décimale par 60.','assert Rational(".5")*60==30 and Rational(".25")*60==15 and Rational(".1")*60==6 and Rational(".75")*60==45'),
E('Le piège de la virgule',r'Paul pense que $1{,}3$ h et 1 h 30 min représentent la même durée. A-t-il raison ? Écrire 1 h 30 min en heures décimales.',r'$\res{\text{Non}}$ : $0{,}3\times60=18$, donc $1{,}3$ h $=1$ h 18 min. Et 1 h 30 min $=\res{1{,}5}$ h, car 30 min est la moitié d’une heure.','Convertir la partie décimale en minutes.','assert Rational(".3")*60==18 and Rational(30,60)==Rational(".5")'),
E('La matinée au collège',r'La frise représente une matinée. Combien de temps Maya passe-t-elle au collège ? Combien de temps dure la récréation ? Combien de temps reste-t-il pour les cours ?',r'De 8 h 25 à 11 h 55 : $\res{3\text{ h }30\text{ min}}$. Récréation : de 10 h 05 à 10 h 20, $\res{15\text{ min}}$. Cours : $\res{3\text{ h }15\text{ min}}$.','Lire les instants sur la frise, puis calculer les durées.','assert (11*60+55)-(8*60+25)==210 and (10*60+20)-(10*60+5)==15 and 210-15==195 and divmod(195,60)==(3,15)',figure='dur-9'),
E('Années bissextiles',r'Une année est bissextile quand son numéro est un multiple de 4 (sauf certaines années de fin de siècle). L’année 2028 sera-t-elle bissextile ? Combien de jours s’écouleront du 1$^{\text{er}}$ janvier 2027 au 1$^{\text{er}}$ janvier 2029 ?',r'$2\,028=4\times507$ : 2028 sera $\res{\text{bissextile}}$. 2027 compte 365 jours et 2028 en compte 366 : $\res{731}$ jours.','Tester la division par 4.','assert 2028%4==0 and 2027%4!=0 and 365+366==731'),
E('Le train',r'Voici les horaires d’un train. Calculer la durée de chaque partie du trajet, puis la durée totale.'+tableau(['Gare','Paris','Lyon','Marseille'],[['Horaire','7 h 52','9 h 48','11 h 32']]),r'Paris–Lyon : $\res{1\text{ h }56\text{ min}}$. Lyon–Marseille : $\res{1\text{ h }44\text{ min}}$. Total : 1 h 56 min + 1 h 44 min $=2$ h 100 min $=\res{3\text{ h }40\text{ min}}$.','Calculer chaque durée, puis convertir 100 min.','assert (9*60+48)-(7*60+52)==116 and (11*60+32)-(9*60+48)==104 and divmod(116+104,60)==(3,40)'),
E('La course',r'Un coureur termine un marathon en 3 h 25 min 40 s. Son ami arrive 12 min 35 s plus tard. Quel est le temps de l’ami ?',r'40 s + 35 s $=75$ s $=1$ min 15 s. 25 min + 12 min + 1 min $=38$ min. Temps : $\res{3\text{ h }38\text{ min }15\text{ s}}$.','Additionner chaque unité, puis convertir les 60.','t=3*3600+25*60+40+12*60+35\nassert divmod(t,3600)==(3,2295) and divmod(2295,60)==(38,15)'),
E('Le bus de ville',r'Sur une ligne de bus, chacun des 12 tronçons se parcourt en 2 min 45 s. Combien de temps dure le trajet complet ?',r'2 min 45 s $=165$ s. $12\times165=1\,980$ s $=\res{33\text{ min}}$, car $1\,980=60\times33$.','Tout convertir en secondes.','assert 12*(2*60+45)==1980 and 1980==60*33'),
E('Les calendriers',r'L’année du calendrier julien dure $365{,}25$ jours, soit environ 11 minutes de plus que l’année des saisons. En combien d’années environ ce décalage atteint-il un jour ? Entre 325 et 1582, quel décalage s’est accumulé ? Pourquoi a-t-on supprimé 10 jours en octobre 1582, lors du passage au calendrier grégorien ?',r'Un jour $=1\,440$ min ; $1\,440=11\times130+10$ : environ $\res{131}$ ans par jour. De 325 à 1582 : $1\,257$ ans, soit $1\,257\times11=13\,827$ min, presque $\res{10}$ jours ($10\times1\,440=14\,400$). On a supprimé ces jours pour recaler le calendrier sur les saisons.','Convertir un jour en minutes et comparer.','assert divmod(1440,11)==(130,10) and 1582-325==1257 and 1257*11==13827 and 9*1440<13827<10*1440'),
E('Le salaire de la journée',r'Un ouvrier travaille 7 h 45 min par jour. Il est payé 14 € de l’heure. Combien gagne-t-il par jour ?',r'7 h 45 min $=7{,}75$ h, car 45 min font $\frac34$ d’heure. Salaire : $7{,}75\times14=\res{108{,}50}$ €.','Passer en heures décimales pour multiplier.','assert Rational(45,60)==Rational(".75") and Rational("7.75")*14==Rational("108.5")')
],reperes=['Lire l’heure et les unités de durée','Calculer des horaires et des durées','Convertir des durées','Heures décimales et problèmes'],deco='grandeurs')
